                case RealtimeItemOperationKind.Unequip:
                {
                    if (value.ItemInstanceId == Guid.Empty
                        || value.ExpectedItemRevision < 0
                        || value.DestinationContainerId == Guid.Empty
                        || value.DestinationSlotIndex < -1)
                    {
                        return false;
                    }

                    break;
                }
                case RealtimeItemOperationKind.Equip:
                {
                    if (value.ItemInstanceId == Guid.Empty
                        || value.ExpectedItemRevision < 0
                        || string.IsNullOrWhiteSpace(value.EquipmentSlotId)
                        || value.EquipmentSlotId.Length > MaximumEquipmentSlotIdLength)
                    {
                        return false;
                    }

                    break;
                }
                case RealtimeItemOperationKind.SplitStack:
                {
                    if (value.ItemInstanceId == Guid.Empty
                        || value.ExpectedItemRevision < 0
                        || value.Quantity < 1
                        || value.DestinationContainerId == Guid.Empty
                        || value.DestinationSlotIndex < -1)
                    {
                        return false;
                    }

                    break;
                }
                case RealtimeItemOperationKind.MergeStacks:
                {
                    if (value.ItemInstanceId == Guid.Empty
                        || value.ExpectedItemRevision < 0
                        || value.TargetItemInstanceId == Guid.Empty
                        || value.ExpectedTargetItemRevision < 0)
                    {
                        return false;
                    }

                    break;
                }
                case RealtimeItemOperationKind.SwapContainerItems:
                {
                    if (value.ItemInstanceId == Guid.Empty
                        || value.ExpectedItemRevision < 0
                        || value.TargetItemInstanceId == Guid.Empty
                        || value.ExpectedTargetItemRevision < 0)
                    {
                        return false;
                    }

                    break;
                }
                case RealtimeItemOperationKind.Destroy:
                {
                    if (value.ItemInstanceId == Guid.Empty
                        || value.ExpectedItemRevision < 0)
                    {
                        return false;
                    }

                    break;
                }
                case RealtimeItemOperationKind.ClaimRecoveryDelivery:
                {
                    if (value.RecoveryDeliveryId == Guid.Empty
                        || value.ExpectedRecoveryDeliveryRevision < 0
                        || value.DestinationContainerId == Guid.Empty
                        || value.Items == null
                        || value.Items.Length < 1
                        || value.Items.Length > MaximumItemOperationItems)
                    {
                        return false;
                    }

                    foreach (var item in value.Items)
                    {
                        if (!IsValidItemRevisionExpectation(item))
                        {
                            return false;
                        }
                    }

                    break;
                }
                default:
                {
                    return false;
                }
            }

            return SatisfiesRules(value);
        }

        /// <summary>
        /// The committed or rejected outcome of an item operation.
        /// </summary>
        public static byte[] EncodeItemOperationResult(RealtimeItemOperationResult result)
        {
            if (!IsValidItemOperationResult(result))
            {
                throw new ArgumentException("Item operation result is invalid.", nameof(result));
            }

            var writer = StartPacket(RealtimeMessageType.ItemOperationResult, SizeOfItemOperationResult(result));
            WriteItemOperationResult(ref writer, result);
            return writer.Finish();
        }

        public static bool TryDecodeItemOperationResult(byte[] data, out RealtimeItemOperationResult result, out string error)
        {
            result = null;
            if (!TryStartPacket(data, RealtimeMessageType.ItemOperationResult, out var reader, out error)
                || !TryReadItemOperationResult(ref reader, out var decoded, out error)
                || !reader.TryFinish(out error))
            {
                return false;
            }

            if (!IsValidItemOperationResult(decoded))
            {
                error = "Item operation result is invalid.";
                return false;
            }

            result = decoded;
            return true;
        }

        private static void WriteItemOperationResult(ref PacketWriter writer, RealtimeItemOperationResult value)
        {
            writer.WriteGuid(value.OperationId);
            writer.WriteByte((byte)value.OperationKind);
            writer.WriteBoolean(value.Succeeded);
            writer.WriteBoolean(value.RequiresInventoryRefresh);
            WriteCarryState(ref writer, value.CarryState);
            if (!value.Succeeded)
            {
                WriteError(ref writer, value.Error);
            }
            writer.WriteByte((byte)value.ItemRevisions.Length);
            foreach (var item in value.ItemRevisions)
            {
                WriteItemRevision(ref writer, item);
            }
            writer.WriteByte((byte)value.ContainerRevisions.Length);
            foreach (var item in value.ContainerRevisions)
            {
                WriteContainerRevision(ref writer, item);
            }
            writer.WriteByte((byte)value.RecoveryDeliveryIds.Length);
            foreach (var item in value.RecoveryDeliveryIds)
            {
                writer.WriteGuid(item);
            }
        }

        private static int SizeOfItemOperationResult(RealtimeItemOperationResult value)
        {
            var size = 43;
            if (!value.Succeeded)
            {
                size += SizeOfError(value.Error);
            }

            size += 1 + (value.ItemRevisions.Length * 24);
            size += 1 + (value.ContainerRevisions.Length * 24);
            size += 1 + (value.RecoveryDeliveryIds.Length * 16);
            return size;
        }

        private static bool TryReadItemOperationResult(ref PacketReader reader, out RealtimeItemOperationResult value, out string error)
        {
            value = null;
            if (!reader.TryReadGuid(out var operationId, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var operationKindByte, out error))
            {
                return false;
            }

            var operationKind = (RealtimeItemOperationKind)operationKindByte;

            if (!reader.TryReadBoolean(out var succeeded, out error))
            {
                return false;
            }

            if (!reader.TryReadBoolean(out var requiresInventoryRefresh, out error))
            {
                return false;
            }

            if (!TryReadCarryState(ref reader, out var carryState, out error))
            {
                return false;
            }

            RealtimeError errorValue = null;
            if (!succeeded)
            {
                if (!TryReadError(ref reader, out errorValue, out error))
                {
                    return false;
                }
            }

            if (!reader.TryReadByte(out var itemRevisionsCount, out error))
            {
                return false;
            }

            if (itemRevisionsCount > MaximumItemResultItemRevisions)
            {
                error = "Item operation result item revisions count is invalid.";
                return false;
            }

            var itemRevisions = new RealtimeItemRevision[itemRevisionsCount];
            for (var index = 0; index < itemRevisions.Length; index++)
            {
                if (!TryReadItemRevision(ref reader, out var element, out error))
                {
                    return false;
                }

                itemRevisions[index] = element;
            }

            if (!reader.TryReadByte(out var containerRevisionsCount, out error))
            {
                return false;
            }

            if (containerRevisionsCount > MaximumItemResultContainerRevisions)
            {
                error = "Item operation result container revisions count is invalid.";
                return false;
            }

            var containerRevisions = new RealtimeContainerRevision[containerRevisionsCount];
            for (var index = 0; index < containerRevisions.Length; index++)
            {
                if (!TryReadContainerRevision(ref reader, out var element, out error))
                {
                    return false;
                }

                containerRevisions[index] = element;
            }

            if (!reader.TryReadByte(out var recoveryDeliveryIdsCount, out error))
            {
                return false;
            }

            if (recoveryDeliveryIdsCount > MaximumItemResultRecoveryDeliveries)
            {
                error = "Item operation result recovery delivery ids count is invalid.";
                return false;
            }

            var recoveryDeliveryIds = new Guid[recoveryDeliveryIdsCount];
            for (var index = 0; index < recoveryDeliveryIds.Length; index++)
            {
                if (!reader.TryReadGuid(out var element, out error))
                {
                    return false;
                }

                recoveryDeliveryIds[index] = element;
            }

            value = new RealtimeItemOperationResult(operationId, operationKind, succeeded, requiresInventoryRefresh, carryState, errorValue, itemRevisions, containerRevisions, recoveryDeliveryIds);
            return true;
        }

        private static bool IsValidItemOperationResult(RealtimeItemOperationResult value)
        {
            if (value == null
                || value.OperationId == Guid.Empty
                || !IsDefined(value.OperationKind)
                || !IsValidCarryState(value.CarryState)
                || !value.Succeeded != (value.Error != null)
                || (value.Error != null && !IsValidError(value.Error))
                || value.ItemRevisions == null
                || value.ItemRevisions.Length > MaximumItemResultItemRevisions
                || value.ContainerRevisions == null
                || value.ContainerRevisions.Length > MaximumItemResultContainerRevisions
                || value.RecoveryDeliveryIds == null
                || value.RecoveryDeliveryIds.Length > MaximumItemResultRecoveryDeliveries)
            {
                return false;
            }

            foreach (var item in value.ItemRevisions)
            {
                if (!IsValidItemRevision(item))
                {
                    return false;
                }
            }

            foreach (var item in value.ContainerRevisions)
            {
                if (!IsValidContainerRevision(item))
                {
                    return false;
                }
            }

            foreach (var item in value.RecoveryDeliveryIds)
            {
                if (item == Guid.Empty)
                {
                    return false;
                }
            }

            return SatisfiesRules(value);
        }

        /// <summary>
        /// A committed quantity change of one of the owner's items that no client intent caused, such as spent arrows.
        /// </summary>
        public static byte[] EncodeOwnerItemQuantityChanged(RealtimeOwnerItemQuantityChanged change)
        {
            if (!IsValidOwnerItemQuantityChanged(change))
            {
                throw new ArgumentException("Owner item quantity changed is invalid.", nameof(change));
            }

            var writer = StartPacket(RealtimeMessageType.OwnerItemQuantityChanged, 61);
            WriteOwnerItemQuantityChanged(ref writer, change);
            return writer.Finish();
        }

        public static bool TryDecodeOwnerItemQuantityChanged(byte[] data, out RealtimeOwnerItemQuantityChanged change, out string error)
        {
            change = null;
            if (!TryStartPacket(data, RealtimeMessageType.OwnerItemQuantityChanged, out var reader, out error)
                || !TryReadOwnerItemQuantityChanged(ref reader, out var decoded, out error)
                || !reader.TryFinish(out error))
            {
                return false;
            }

            if (!IsValidOwnerItemQuantityChanged(decoded))
            {
                error = "Owner item quantity changed is invalid.";
                return false;
            }

            change = decoded;
            return true;
        }

        private static void WriteOwnerItemQuantityChanged(ref PacketWriter writer, RealtimeOwnerItemQuantityChanged value)
        {
            writer.WriteByte((byte)value.Reason);
            writer.WriteInt64(value.PreviousItemStateRevision);
            WriteCarryState(ref writer, value.CarryState);
            writer.WriteGuid(value.ItemInstanceId);
            writer.WriteInt32(value.Quantity);
            writer.WriteInt64(value.ItemRevision);
        }

        private static bool TryReadOwnerItemQuantityChanged(ref PacketReader reader, out RealtimeOwnerItemQuantityChanged value, out string error)
        {
            value = null;
            if (!reader.TryReadByte(out var reasonByte, out error))
            {
                return false;
            }

            var reason = (RealtimeItemQuantityChangeReason)reasonByte;

            if (!reader.TryReadInt64(out var previousItemStateRevision, out error))
            {
                return false;
            }

            if (!TryReadCarryState(ref reader, out var carryState, out error))
            {
                return false;
            }

            if (!reader.TryReadGuid(out var itemInstanceId, out error))
            {
                return false;
            }

            if (!reader.TryReadInt32(out var quantity, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var itemRevision, out error))
            {
                return false;
            }

            value = new RealtimeOwnerItemQuantityChanged(reason, previousItemStateRevision, carryState, itemInstanceId, quantity, itemRevision);
            return true;
        }

        private static bool IsValidOwnerItemQuantityChanged(RealtimeOwnerItemQuantityChanged value)
        {
            if (value == null
                || !IsDefined(value.Reason)
                || value.PreviousItemStateRevision < 0
                || !IsValidCarryState(value.CarryState)
                || value.ItemInstanceId == Guid.Empty
                || value.Quantity < 0
                || value.ItemRevision < 0)
            {
                return false;
            }

            return SatisfiesRules(value);
        }

        private static void WriteCarryState(ref PacketWriter writer, RealtimeCarryState value)
        {
            writer.WriteInt64(value.ItemStateRevision);
            writer.WriteInt64(value.CarriedWeight);
            writer.WriteInt64(value.CarryCapacity);
        }

        private static bool TryReadCarryState(ref PacketReader reader, out RealtimeCarryState value, out string error)
        {
            value = null;
            if (!reader.TryReadInt64(out var itemStateRevision, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var carriedWeight, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var carryCapacity, out error))
            {
                return false;
            }

            value = new RealtimeCarryState(itemStateRevision, carriedWeight, carryCapacity);
            return true;
        }

        private static bool IsValidCarryState(RealtimeCarryState value)
        {
            if (value == null
                || value.ItemStateRevision < 0
                || value.CarriedWeight < 0
                || value.CarryCapacity < 1)
            {
                return false;
            }

            return true;
        }

        private static void WriteItemRevisionExpectation(ref PacketWriter writer, RealtimeItemRevisionExpectation value)
        {
            writer.WriteGuid(value.ItemInstanceId);
            writer.WriteInt64(value.Revision);
        }

        private static bool TryReadItemRevisionExpectation(ref PacketReader reader, out RealtimeItemRevisionExpectation value, out string error)
        {
            value = null;
            if (!reader.TryReadGuid(out var itemInstanceId, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var revision, out error))
            {
                return false;
            }

            value = new RealtimeItemRevisionExpectation(itemInstanceId, revision);
            return true;
        }

        private static bool IsValidItemRevisionExpectation(RealtimeItemRevisionExpectation value)
        {
            if (value == null
                || value.ItemInstanceId == Guid.Empty
                || value.Revision < 0)
            {
                return false;
            }

            return true;
        }

        private static void WriteItemRevision(ref PacketWriter writer, RealtimeItemRevision value)
        {
            writer.WriteGuid(value.ItemInstanceId);
            writer.WriteInt64(value.Revision);
        }

        private static bool TryReadItemRevision(ref PacketReader reader, out RealtimeItemRevision value, out string error)
        {
            value = null;
            if (!reader.TryReadGuid(out var itemInstanceId, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var revision, out error))
            {
                return false;
            }

            value = new RealtimeItemRevision(itemInstanceId, revision);
            return true;
        }

        private static bool IsValidItemRevision(RealtimeItemRevision value)
        {
            if (value == null
                || value.ItemInstanceId == Guid.Empty
                || value.Revision < 0)
            {
                return false;
            }

            return true;
        }

        private static void WriteContainerRevision(ref PacketWriter writer, RealtimeContainerRevision value)
        {
            writer.WriteGuid(value.ContainerId);
            writer.WriteInt64(value.Revision);
        }

        private static bool TryReadContainerRevision(ref PacketReader reader, out RealtimeContainerRevision value, out string error)
        {
            value = null;
            if (!reader.TryReadGuid(out var containerId, out error))
            {
                return false;
            }

            if (!reader.TryReadInt64(out var revision, out error))
